// spec: .qa/e2e/specs/expert.md (3.1) · кейс .qa/tests/expert/EXP-004.md
// seed: tests/seed.expert.spec.ts
// ПРЕДОХРАНИТЕЛЬ: запросы записи к supabase отклоняются (blockRuleWrites); «שמירה לכולם» никогда не нажимается,
// если окно подтверждения всё же появилось — тест падает и жмёт «ביטול» (afterEach). Пояснение — с префиксом QA-AUTO-.
// Не входит: «0,1» (запятая) проходит без ошибки — открытый баг #1b17df.
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { blockRuleWrites, openExpertScreen, field, explanation, saveButton, confirmTitle, cancelConfirmIfShown } from '../helpers/expert';

test.use({ storageState: path.join(__dirname, '../../../auth/expert.json') });

const RANGE_MSG = 'צריך להיות מספר בין 5 ל-120 שניות';
const CASES: { value: string; msg: string | RegExp }[] = [
  { value: '999', msg: RANGE_MSG },
  { value: '0', msg: RANGE_MSG },
  { value: '-5', msg: RANGE_MSG },
  { value: '', msg: /^צריך/ },
  { value: 'abc', msg: /^צריך/ },
];

test.describe('Экран «חוקי זיהוי» — эксперт, неверные значения', () => {
  test.afterEach(async ({ page }) => { await cancelConfirmIfShown(page); });

  test('«חוסר תנועה» вне диапазона (999, 0, −5, пусто, abc): сообщение, «יש שדות שצריך לתקן», без окна подтверждения, не сохранено #89216b @desktop @prod-safe', async ({ page }) => {
    const writes = await blockRuleWrites(page);
    await openExpertScreen(page);
    const motion = field(page, 'חוסר תנועה');
    const original = await motion.inputValue();

    // Пояснение заполнено — чтобы ошибкой было только число
    await explanation(page).fill('QA-AUTO- בדיקה אוטומטית, לא לשמור');

    for (const c of CASES) {
      await test.step(`«חוסר תנועה» = «${c.value}»`, async () => {
        await motion.fill(c.value);
        // Сообщение под полем — AC4 «מופיעה הודעה עם הטווח המותר»
        const msg = typeof c.msg === 'string'
          ? page.getByText(c.msg, { exact: true })
          : page.getByText(c.msg);
        await saveButton(page).click();
        await expect(msg.filter({ visible: true }).first()).toBeVisible();
        // Плашка и отсутствие окна подтверждения — AC4 «והחוקים לא נשמרים»
        await expect(page.getByText('יש שדות שצריך לתקן', { exact: true }).filter({ visible: true })).toBeVisible();
        await expect(confirmTitle(page)).toHaveCount(0);
        expect(writes.saveCalls, 'запрос сохранения не отправлялся').toBe(0);
      });
    }

    // Ушли без сохранения: после перезагрузки исходное значение
    await page.reload();
    await expect(field(page, 'חוסר תנועה')).toHaveValue(original);
    expect(writes.saveCalls).toBe(0);
  });
});
